const item = $input.first();
const triggerData = $('Telegram Trigger').first().json;

const chatId = triggerData.message.chat.id;
const text = (triggerData.message.text || '').trim();
const firstName = triggerData.message.from.first_name || 'Гость';

// Читаем сессию из Supabase (Get Session node)
let step = 0;
let sessionData = {};

try {
  const sessionRow = $('Get Session').first().json;
  if (sessionRow && sessionRow.chat_id) {
    step = sessionRow.step || 0;
    sessionData = sessionRow.data || {};
  }
} catch(e) {
  step = 0;
  sessionData = {};
}

let replyText = '';
let nextStep = step;

if (text === '/start' || step === 0) {
  replyText = `Привет, ${firstName}! 👋\nДобро пожаловать в систему бронирования.\n\nКак вас зовут? (введите имя и фамилию)`;
  nextStep = 1;

} else if (step === 1) {
  sessionData.guest_name = text;
  replyText = `Отлично, ${text}! 📅\nНа какую дату бронируем?\n(формат: ДД.ММ.ГГГГ, например 25.05.2025)`;
  nextStep = 2;

} else if (step === 2) {
  const dateRegex = /^(\d{2})\.(\d{2})\.(\d{4})$/;
  if (!dateRegex.test(text)) {
    replyText = '❌ Неверный формат даты. Пожалуйста, введите дату в формате ДД.ММ.ГГГГ';
    nextStep = 2;
  } else {
    const parts = text.split('.');
    sessionData.reservation_date = `${parts[2]}-${parts[1]}-${parts[0]}`;
    replyText = '⏰ На какое время?\n(формат: ЧЧ:ММ, например 19:30)';
    nextStep = 3;
  }

} else if (step === 3) {
  const timeRegex = /^(\d{2}):(\d{2})$/;
  if (!timeRegex.test(text)) {
    replyText = '❌ Неверный формат времени. Пожалуйста, введите время в формате ЧЧ:ММ';
    nextStep = 3;
  } else {
    sessionData.reservation_time = text;
    replyText = '👥 Сколько гостей будет?';
    nextStep = 4;
  }

} else if (step === 4) {
  const count = parseInt(text);
  if (isNaN(count) || count < 1 || count > 20) {
    replyText = '❌ Пожалуйста, введите число от 1 до 20';
    nextStep = 4;
  } else {
    sessionData.party_size = count;
    replyText = '📧 Ваш email для подтверждения бронирования?';
    nextStep = 5;
  }

} else if (step === 5) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(text)) {
    replyText = '❌ Неверный формат email. Попробуйте ещё раз';
    nextStep = 5;
  } else {
    sessionData.guest_email = text;
    replyText = '📱 Ваш номер телефона?';
    nextStep = 6;
  }

} else if (step === 6) {
  sessionData.guest_phone = text;
  replyText = `✅ Проверьте данные:\n\n👤 ${sessionData.guest_name}\n📅 ${sessionData.reservation_date}\n⏰ ${sessionData.reservation_time}\n👥 ${sessionData.party_size} гостей\n📧 ${sessionData.guest_email}\n📱 ${sessionData.guest_phone}\n\nПодтвердить? (да / нет)`;
  nextStep = 7;

} else if (step === 7) {
  if (text.toLowerCase() === 'да') {
    replyText = '⏳ Сохраняем вашу бронь...';
    nextStep = 8;
  } else {
    replyText = '❌ Бронирование отменено. Напишите /start чтобы начать заново.';
    nextStep = 0;
    sessionData = {};
  }
}

return [{
  json: {
    chatId,
    replyText,
    step: nextStep,
    sessionData,
    firstName,
    readyToSave: nextStep === 8
  }
}];

const data = $('Code in JavaScript').first().json.sessionData;

// Конвертируем дату из формата ГГГГ-ММ-ДД (уже конвертирована в Code node)
return [{
  json: {
    restaurant_id: 'e12f1eae-f48d-4c5f-ac9b-b9fd0f84e754',
    guest_name: data.guest_name,
    guest_email: data.guest_email,
    guest_phone: data.guest_phone,
    party_size: data.party_size,
    reservation_date: data.reservation_date,
    reservation_time: data.reservation_time,
    status: 'confirmed',
    source: 'telegram',
    reminder_sent: false,
    notes: '',
    reserved_at: new Date().toISOString()
  }
}];

